/**
 * 用系统语音朗读英文：词典卡片、单词本、语音室共用。
 *
 * 这一版治四件「点了没声、半天才出声」的事：
 *
 * 1. 音色要提前认下来。iPad / Safari 上没指定英语音色时它一声不吭，
 *    而音色列表是异步到的（voiceschanged），所以要挂在事件上等它到货，
 *    之后每次开口都用同一个记下来的音色。
 * 2. 音色列表迟到（Chrome / 平板冷启动时就是空表）时别硬读：
 *    先等 voiceschanged 到货再开口，最多等一小拍，等不到才交给引擎默认音色。
 * 3. 不要 cancel() 紧跟着 speak()。iOS 会把挨着取消的那一句吞掉，
 *    桌面 Chrome 也要为这次打断多等小半秒 —— 而「点一下就出声」时
 *    本来就没人在说话。真有人在说才打断，且隔一拍再开口。
 * 4. 引擎第一次发音最慢。第一个手势里先静音「开嗓」一次，
 *    之后点词即读；开嗓那一句要是卡在队列里没播出来，真词来了就把它收掉，
 *    别让它堵住后面。
 */

export interface SpeakOptions {
  /** 覆盖语言，比如语音室的英音。默认 en-US。 */
  lang?: string;
  /** 语速。默认 0.9，比原先的 0.86 略快一点。 */
  rate?: number;
}

const DEFAULT_LANG = "en-US";
const DEFAULT_RATE = 0.9;
/** 音色列表到货最多等这么久，等不到就先交给引擎默认音色读。 */
const VOICE_WAIT_MS = 900;

/** 已认下来的音色，按语言分类。 */
const voiceCache = new Map<string, SpeechSynthesisVoice>();
let voicesHooked = false;
let primed = false;
let primePending = false;

function synth(): SpeechSynthesis | null {
  return typeof window !== "undefined" && "speechSynthesis" in window
    ? window.speechSynthesis
    : null;
}

function pickVoice(lang: string): SpeechSynthesisVoice | null {
  const s = synth();
  if (!s) return null;
  const voices = s.getVoices();
  if (voices.length === 0) return null;
  const cached = voiceCache.get(lang);
  if (cached && voices.includes(cached)) return cached;
  const want = lang.toLowerCase().replace("_", "-");
  const prefix = want.slice(0, 2);
  const normalize = (voice: SpeechSynthesisVoice) =>
    voice.lang.toLowerCase().replace("_", "-");
  // 先说这个口音；没有就退到同语言的；再没有就不指定，交给引擎默认。
  const found =
    voices.find((voice) => normalize(voice) === want) ??
    voices.find((voice) => normalize(voice).startsWith(prefix)) ??
    null;
  if (found) voiceCache.set(lang, found);
  return found;
}

/**
 * 音色列表是异步到的：Chrome 要先说一句才列全，Safari 走 voiceschanged。
 * 到货后清一次缓存，下次开口自然重新挑。
 */
function hookVoices() {
  const s = synth();
  if (!s || voicesHooked) return;
  voicesHooked = true;
  pickVoice(DEFAULT_LANG);
  if (typeof s.addEventListener === "function") {
    s.addEventListener("voiceschanged", () => {
      voiceCache.clear();
      pickVoice(DEFAULT_LANG);
    });
  }
}

/**
 * 第一个用户手势里静音「开嗓」：唤醒引擎，Safari 也借此拿到出声许可。
 * 一个空格、音量 0，人耳听不见；真读单词时它早结束了。
 */
export function primeSpeech() {
  const s = synth();
  if (!s || primed) return;
  primed = true;
  hookVoices();
  try {
    s.resume();
    const utterance = new SpeechSynthesisUtterance(" ");
    utterance.lang = DEFAULT_LANG;
    utterance.rate = 1;
    utterance.volume = 0;
    const voice = pickVoice(DEFAULT_LANG);
    if (voice) utterance.voice = voice;
    primePending = true;
    utterance.onend = () => {
      primePending = false;
    };
    utterance.onerror = () => {
      primePending = false;
    };
    s.speak(utterance);
    // 万一这一声卡在队列里（个别 iOS / 平板版本不回调 onend、也不开播），
    // 别让它堵住后面：在说、或排着没动静，都收掉。
    window.setTimeout(() => {
      if (primePending && (s.speaking || s.pending)) s.cancel();
      primePending = false;
    }, 900);
  } catch {
    // 不支持就当没这回事。
  }
}

/**
 * 把一句话交给引擎。音色没认下来时先等 voiceschanged（平板/Chrome 冷启动
 * 常见空表），到点还没等到就直接读 —— 有英语音色最好，没有也别一声不吭。
 */
function utterWhenReady(value: string, lang: string, rate: number) {
  const s = synth();
  if (!s) return;
  const speak = () => {
    const utterance = new SpeechSynthesisUtterance(value);
    utterance.lang = lang;
    utterance.rate = rate;
    const voice = pickVoice(lang);
    if (voice) utterance.voice = voice;
    s.speak(utterance);
  };
  // 有英语音色，或者列表已经到货（只是没有英语的）——直接读，不再干等。
  if (pickVoice(lang) || s.getVoices().length > 0) {
    speak();
    return;
  }
  let released = false;
  const release = () => {
    if (released) return;
    released = true;
    if (typeof s.removeEventListener === "function") {
      s.removeEventListener("voiceschanged", onVoices);
    }
    speak();
  };
  const onVoices = () => release();
  if (typeof s.addEventListener === "function") {
    s.addEventListener("voiceschanged", onVoices);
  }
  window.setTimeout(release, VOICE_WAIT_MS);
}

/**
 * 读一段英文。正在读别的就先打断、隔一拍再开口；空着就直接读。
 * 返回是否真的交给了引擎（调用方据此提示「浏览器不支持」）。
 */
export function speakEnglish(text: string, options: SpeakOptions = {}) {
  const s = synth();
  const value = text.trim();
  if (!s || !value) return false;
  hookVoices();
  const lang = options.lang ?? DEFAULT_LANG;
  const rate = options.rate ?? DEFAULT_RATE;

  const utter = () => utterWhenReady(value, lang, rate);

  // 真词要开口了，开嗓的看门狗别再动队列。
  const wasPriming = primePending;
  primePending = false;
  try {
    s.resume();
  } catch {
    // 个别浏览器 resume 无意义，忽略。
  }
  if (s.speaking || s.pending) {
    // 不管正读的是上一处、还是我们自己的静音开嗓，一律：先打断，
    // 隔一拍再开口（iOS 上同拍会被吞）。开嗓那一句是听不见的，
    // 收掉它最干净 —— 万一它卡住没播出来，也不至于把真词堵在后面。
    s.cancel();
    window.setTimeout(utter, 60);
    return true;
  }
  // 空着的时候直接读：不 cancel、不等待。
  utter();
  return true;
}

/** 当前浏览器有没有语音朗读。 */
export function speakingSupported() {
  return synth() !== null;
}

// 第一个手势里自动开嗓（capture 期，抢在按钮的 click 之前）。
// touchstart 兜底：老一点的平板 WebView 不派发 pointer 事件。
if (typeof window !== "undefined") {
  const prime = () => primeSpeech();
  window.addEventListener("pointerdown", prime, { once: true, capture: true });
  window.addEventListener("keydown", prime, { once: true, capture: true });
  window.addEventListener("touchstart", prime, {
    once: true,
    capture: true,
    passive: true,
  });
}
